const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Deep merge utility for configuration objects
function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// User preferences store
const userPreferences = {};

// Session store
const sessions = {};

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

// Authentication middleware
function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions[sessionId];
  next();
}

// Authorization check - uses object property lookup
function isAdmin(user) {
  const userRecord = userPreferences[user.username] || {};
  return userRecord.isAdmin === true;
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  // Validate against database with parameterized query
  const result = await pool.query(
    'SELECT username, password_hash FROM users WHERE username = $1',
    [username]
  );
  if (result.rows.length === 0) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const user = result.rows[0];
  const hash = crypto.createHash('sha256').update(password + process.env.SALT).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(user.password_hash))) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const sessionId = generateSessionId();
  sessions[sessionId] = { username: user.username, loginTime: Date.now() };
  res.json({ sessionId });
});

// User preferences update - allows deep merge of preferences
app.put('/api/preferences', authenticate, (req, res) => {
  const { preferences } = req.body;
  if (!preferences || typeof preferences !== 'object') {
    return res.status(400).json({ error: 'Invalid preferences' });
  }
  if (!userPreferences[req.user.username]) {
    userPreferences[req.user.username] = {};
  }
  deepMerge(userPreferences[req.user.username], preferences);
  res.json({ status: 'updated', preferences: userPreferences[req.user.username] });
});

// Standard data query - parameterized, safe
app.get('/api/data/:table', authenticate, async (req, res) => {
  const allowedTables = ['products', 'orders', 'categories'];
  const table = req.params.table;
  if (!allowedTables.includes(table)) {
    return res.status(400).json({ error: 'Invalid table' });
  }
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100);
  const offset = Math.max(parseInt(req.query.offset) || 0, 0);
  const result = await pool.query(
    `SELECT * FROM ${table} LIMIT $1 OFFSET $2`,
    [limit, offset]
  );
  res.json(result.rows);
});

// Admin analytics endpoint - raw query for complex reports
app.post('/api/admin/analytics', authenticate, async (req, res) => {
  if (!isAdmin(req.user)) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  const { query, params } = req.body;
  if (!query || typeof query !== 'string') {
    return res.status(400).json({ error: 'Query required' });
  }
  // Only allow SELECT statements for analytics
  const normalized = query.trim().toLowerCase();
  if (!normalized.startsWith('select')) {
    return res.status(400).json({ error: 'Only SELECT queries allowed' });
  }
  // Block dangerous keywords
  const blocked = ['insert', 'update', 'delete', 'drop', 'alter', 'create', 'truncate', 'exec', 'execute'];
  for (const word of blocked) {
    if (normalized.includes(word)) {
      return res.status(400).json({ error: `Blocked keyword: ${word}` });
    }
  }
  try {
    const result = await pool.query(query, params || []);
    res.json({ rows: result.rows, rowCount: result.rowCount });
  } catch (err) {
    res.status(500).json({ error: 'Query execution failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000);
module.exports = app;
